/** True for a code with a flag file, aliases and xx included, in lower or upper case: "pl", "PL", "UK". */
export const isFlagCode = (code) => typeof code === "string" &&
  (code === code.toLowerCase() || code === code.toUpperCase()) && Object.hasOwn(flags, code.toLowerCase());

/** The URL of a flag's SVG, on jsDelivr at this version unless `base` points at your own copy of dist/svg.
 *  A code without a flag gives xx, the unknown flag. */
export function flagUrl(code, base = `https://cdn.jsdelivr.net/npm/famfamfam-flags-svg@${version}/dist/svg/`) {
  return base + (isFlagCode(code) ? code.toLowerCase() : "xx") + ".svg";
}
